/**
 * What `commitAgent` checks before it touches the filesystem.
 *
 * Publishing an Agent package writes a persona, copies the skill folders the
 * user selected, and writes the skills the generator invented. Every one of
 * those is a chance to produce a package the runtime cannot load, and the
 * damage is not confined to the bad skill: an overwrite removes the Agent that
 * was there first. So the whole batch — imported bytes, generated bytes, and
 * the folder names both would claim — is read and checked before anything is
 * created or removed.
 */

import test from "node:test";
import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

import { commitAgent } from "../../domains/agent-generator/index.js";
import { findSkillSpecViolations } from "../../domains/agent-generator/skill-spec-validation.js";

const AGENT_NAME = "drafting-completeness-lawyer";
const PERSONA = `---\nname: ${AGENT_NAME}\ndescription: Reviews drafts.\n---\n\n# Draft\n`;

function withTempRepo(run: (repoRoot: string) => Promise<void>): Promise<void> {
  const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), "skill-preflight-"));
  return run(repoRoot).finally(() => {
    fs.rmSync(repoRoot, { recursive: true, force: true });
  });
}

function skillBody(name: string, description = "Review a draft. Use when signing."): string {
  return `---\nname: ${name}\ndescription: ${description}\n---\n\n# ${name}\n`;
}

/** A selectable skill folder on disk, outside any Agent package. */
function writeSourceSkill(
  repoRoot: string,
  folderName: string,
  body: string | null,
): string {
  const folder = path.join(repoRoot, "sources", folderName);
  fs.mkdirSync(folder, { recursive: true });
  if (body !== null) fs.writeFileSync(path.join(folder, "SKILL.md"), body);
  return folder;
}

/** Every file under `root`, by repo-relative path, with its exact bytes. */
function snapshot(root: string): Record<string, string> {
  const files: Record<string, string> = {};
  const walk = (directory: string): void => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory()) walk(absolute);
      else if (entry.isFile()) {
        files[path.relative(root, absolute)] = fs.readFileSync(absolute, "utf8");
      }
    }
  };
  walk(root);
  return files;
}

function agentFolder(repoRoot: string): string {
  return path.join(repoRoot, "agents", AGENT_NAME);
}

/**
 * Nothing was created for this Agent, not even the parent it would live in.
 *
 * Asserting only that `agents/<name>` is absent would still pass an
 * implementation that made `agents/` before deciding whether to publish, which
 * is exactly the ordering this preflight exists to fix.
 */
function assertNothingPublished(repoRoot: string): void {
  assert.equal(
    fs.existsSync(path.join(repoRoot, "agents")),
    false,
    "a refused batch creates nothing, including the agents directory",
  );
}

test("an imported skill that breaks the specification is refused before anything is written", async () => {
  await withTempRepo(async (repoRoot) => {
    // The folder is named `contract-review` but its frontmatter calls itself
    // something else, so the runtime would never find it under the name it
    // declares.
    const source = writeSourceSkill(
      repoRoot,
      "contract-review",
      skillBody("something-else"),
    );

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("a selected skill folder with no SKILL.md fails rather than being skipped", async () => {
  await withTempRepo(async (repoRoot) => {
    // The user asked for this folder. Publishing the Agent without it and
    // saying nothing would hand back a package missing a skill it was told to
    // carry.
    const source = writeSourceSkill(repoRoot, "contract-review", null);

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("two generated skills with one name are refused", async () => {
  await withTempRepo(async (repoRoot) => {
    // Both would be written to the same folder, so the second would silently
    // replace the first and the result would report two skills that are one.
    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [],
        generatedSkills: [
          { name: "contract-review", body: skillBody("contract-review") },
          { name: "contract-review", body: skillBody("contract-review") },
        ],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("two imported skills with one basename are refused", async () => {
  await withTempRepo(async (repoRoot) => {
    const first = writeSourceSkill(repoRoot, "contract-review", skillBody("contract-review"));
    const secondParent = path.join(repoRoot, "other-sources");
    fs.mkdirSync(path.join(secondParent, "contract-review"), { recursive: true });
    fs.writeFileSync(
      path.join(secondParent, "contract-review", "SKILL.md"),
      skillBody("contract-review", "A different review. Use when reviewing."),
    );

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [first, path.join(secondParent, "contract-review")],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("an imported and a generated skill claiming one folder are refused", async () => {
  await withTempRepo(async (repoRoot) => {
    // Copying the folder and then writing the generated SKILL.md over it would
    // leave one folder holding another skill's supporting files.
    const source = writeSourceSkill(repoRoot, "contract-review", skillBody("contract-review"));
    fs.writeFileSync(path.join(source, "reference.md"), "# Imported reference\n");

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
        generatedSkills: [
          { name: "contract-review", body: skillBody("contract-review") },
        ],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("a refused batch leaves an existing overwrite target exactly as it was", async () => {
  await withTempRepo(async (repoRoot) => {
    const existing = agentFolder(repoRoot);
    fs.mkdirSync(path.join(existing, "skills", "existing-skill"), { recursive: true });
    fs.writeFileSync(path.join(existing, `${AGENT_NAME}.md`), "# The Agent that is already here\n");
    fs.writeFileSync(
      path.join(existing, "skills", "existing-skill", "SKILL.md"),
      skillBody("existing-skill"),
    );
    const before = snapshot(existing);
    // The bad input is an imported skill, which is the half the overwrite used
    // to reach: the target was removed first and the copy failed afterwards.
    const source = writeSourceSkill(
      repoRoot,
      "contract-review",
      "---\nname: contract-review\n---\n\n# No description\n",
    );

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
        overwrite: true,
      }),
      /contract-review/u,
    );

    assert.deepEqual(snapshot(existing), before);
  });
});

test("a valid batch publishes every skill under the exact name it declared", async () => {
  await withTempRepo(async (repoRoot) => {
    const source = writeSourceSkill(repoRoot, "contract-review", skillBody("contract-review"));
    fs.writeFileSync(path.join(source, "reference.md"), "# Imported reference\n");

    const result = await commitAgent({
      repoRoot,
      approvedName: AGENT_NAME,
      personaMarkdown: PERSONA,
      skillPaths: [source],
      generatedSkills: [
        { name: "drafting-review", body: skillBody("drafting-review") },
      ],
    });

    assert.deepEqual(result.importedSkills, ["contract-review"]);
    assert.deepEqual(result.generatedSkills, ["drafting-review"]);
    const skillsDir = path.join(agentFolder(repoRoot), "skills");
    assert.deepEqual(fs.readdirSync(skillsDir).sort(), ["contract-review", "drafting-review"]);
    assert.equal(
      fs.readFileSync(path.join(skillsDir, "contract-review", "reference.md"), "utf8"),
      "# Imported reference\n",
    );
    assert.equal(
      fs.readFileSync(path.join(skillsDir, "drafting-review", "SKILL.md"), "utf8"),
      skillBody("drafting-review"),
    );
  });
});

function problems(source: string, folderName = "contract-review"): string[] {
  return findSkillSpecViolations({
    source,
    folderName,
    skillPath: `skills/${folderName}/SKILL.md`,
  }).map((violation) => violation.problem);
}

function frontmatter(extra: string): string {
  return `---\nname: contract-review\ndescription: Review a draft. Use when signing.\n${extra}\n---\n\n# Review\n`;
}

test("an optional frontmatter key of the wrong type is a violation", () => {
  // The repository's own YAML reader is lenient: it will hand back a number for
  // `license`, a bare string for `metadata`, and a list for `allowed-tools`.
  // The specification says otherwise, and a host that reads the skill will too.
  assert.match(problems(frontmatter("license: 42")).join("; "), /license/u);
  assert.match(problems(frontmatter("compatibility: 7")).join("; "), /compatibility/u);
  assert.match(problems(frontmatter("metadata: not-a-map")).join("; "), /metadata/u);
  assert.match(
    problems(frontmatter("metadata:\n  author: me\n  version: 1")).join("; "),
    /metadata/u,
    "a metadata value that is not a string is not a string",
  );
  assert.match(
    problems(frontmatter("allowed-tools:\n  - Read\n  - Write")).join("; "),
    /allowed-tools/u,
  );
});

test("optional frontmatter keys of the right type are accepted", () => {
  assert.deepEqual(
    problems(
      frontmatter(
        "license: MIT\ncompatibility: claude-code\nmetadata:\n  author: me\nallowed-tools: Read Write",
      ),
    ),
    [],
  );
});

test("an inline description carrying a colon must use a folded scalar", () => {
  // A real YAML reader takes `description: Review a draft: check clauses` as a
  // mapping and refuses it. This repository's reader is lenient enough to hand
  // back a string, so the rule has to be checked rather than discovered.
  assert.match(
    problems(
      "---\nname: contract-review\ndescription: Review a draft: check clauses. Use when signing.\n---\n\n# Review\n",
    ).join("; "),
    /folded/u,
  );
  assert.deepEqual(
    problems(
      "---\nname: contract-review\ndescription: >\n  Review a draft: check clauses.\n  Use when signing.\n---\n\n# Review\n",
    ),
    [],
  );
  // Project policy names one allowed form. A quoted scalar parses, but the rule
  // is `description: >`, so accepting quotes would let two spellings of the
  // same thing through and only one of them be the one the policy states.
  assert.match(
    problems(
      '---\nname: contract-review\ndescription: "Review a draft: check clauses."\n---\n\n# Review\n',
    ).join("; "),
    /folded/u,
  );
  assert.match(
    problems(
      "---\nname: contract-review\ndescription: |\n  Review a draft: check clauses.\n---\n\n# Review\n",
    ).join("; "),
    /folded/u,
  );
});

test("a generated skill name carrying surrounding whitespace is refused", async () => {
  await withTempRepo(async (repoRoot) => {
    // Trimming it would publish a folder the batch never approved under that
    // exact string, which is the rename the approved-name rule forbids.
    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [],
        generatedSkills: [
          { name: " contract-review ", body: skillBody("contract-review") },
        ],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("an imported folder whose basename carries whitespace is refused", async () => {
  await withTempRepo(async (repoRoot) => {
    // Validating a trimmed name and then copying under the untrimmed one would
    // publish a folder nothing checked.
    const source = writeSourceSkill(repoRoot, " contract-review ", skillBody("contract-review"));

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("a selected SKILL.md that cannot be read fails with the path it came from", async () => {
  await withTempRepo(async (repoRoot) => {
    // A directory where the file should be is not an absent file. Reading it as
    // "no SKILL.md" would report the wrong problem, and swallowing the reason
    // would leave nobody able to act on it.
    const source = writeSourceSkill(repoRoot, "contract-review", null);
    fs.mkdirSync(path.join(source, "SKILL.md"));

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
      }),
      (error: unknown) =>
        error instanceof Error &&
        error.message.includes(path.join(source, "SKILL.md")) &&
        !/no SKILL\.md to publish/u.test(error.message),
    );

    assertNothingPublished(repoRoot);
  });
});

test("a symlinked SKILL.md is refused rather than validated and then dropped", async () => {
  await withTempRepo(async (repoRoot) => {
    // Reading follows the link, so the bytes look fine; copying does not, so
    // the published folder would have no SKILL.md at all. The two must not be
    // able to disagree.
    const real = path.join(repoRoot, "elsewhere", "SKILL.md");
    fs.mkdirSync(path.dirname(real), { recursive: true });
    fs.writeFileSync(real, skillBody("contract-review"));
    const source = writeSourceSkill(repoRoot, "contract-review", null);
    fs.symlinkSync(real, path.join(source, "SKILL.md"));

    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [source],
      }),
      /contract-review/u,
    );

    assertNothingPublished(repoRoot);
  });
});

test("the published SKILL.md is the one that was validated", async () => {
  await withTempRepo(async (repoRoot) => {
    const source = writeSourceSkill(repoRoot, "contract-review", skillBody("contract-review"));
    fs.writeFileSync(path.join(source, "reference.md"), "# Imported reference\n");
    const validated = fs.readFileSync(path.join(source, "SKILL.md"), "utf8");

    const result = await commitAgent({
      repoRoot,
      approvedName: AGENT_NAME,
      personaMarkdown: PERSONA,
      skillPaths: [source],
      generatedSkills: [{ name: "drafting-review", body: skillBody("drafting-review") }],
    });

    assert.deepEqual(result.importedSkills, ["contract-review"]);
    const published = path.join(agentFolder(repoRoot), "skills", "contract-review");
    assert.equal(fs.readFileSync(path.join(published, "SKILL.md"), "utf8"), validated);
    assert.equal(
      fs.readFileSync(path.join(published, "reference.md"), "utf8"),
      "# Imported reference\n",
    );
  });
});

test("an empty compatibility is a violation", () => {
  // Optional, but 1-500 characters when it is there. An empty string declares a
  // compatibility and says nothing.
  assert.match(problems(frontmatter('compatibility: ""')).join("; "), /compatibility/u);
});

test("a frontmatter name is taken exactly as declared", () => {
  // A quoted name keeps its spaces. Trimming it before the check would let a
  // name that is not exact kebab pass, and match a folder it does not name.
  assert.match(
    problems(
      '---\nname: " contract-review "\ndescription: Review a draft. Use when signing.\n---\n\n# Review\n',
    ).join("; "),
    /name/u,
  );
});

test("only a real folded block indicator is a folded scalar", () => {
  // `>` followed by text on the same line is not a block indicator: this
  // repository's reader stores the literal `> ...` string, so the colon rule
  // still applies to it. `>+` is not a form this reader supports at all — it
  // hands back the indicator itself as the description.
  assert.match(
    problems(
      "---\nname: contract-review\ndescription: > Review a draft: check clauses.\n---\n\n# Review\n",
    ).join("; "),
    /folded/u,
  );
  assert.match(
    problems(
      "---\nname: contract-review\ndescription: >+\n  Review a draft: check clauses.\n---\n\n# Review\n",
    ).join("; "),
    /folded/u,
  );
  // The two spellings the reader really folds stay accepted.
  for (const indicator of [">", ">-"]) {
    assert.deepEqual(
      problems(
        `---\nname: contract-review\ndescription: ${indicator}\n  Review a draft: check clauses.\n---\n\n# Review\n`,
      ),
      [],
      indicator,
    );
  }
});

test("the description length is the declared length, not a collapsed one", () => {
  // Collapsing runs of whitespace before measuring lets a description well over
  // the limit through: the text the host has to hold is the text as declared.
  const padded = `Review a draft.${" ".repeat(1100)}Use when signing.`;
  assert.equal(padded.length > 1024, true, "fixture check: the declared text is over the limit");
  assert.match(
    problems(
      `---\nname: contract-review\ndescription: "${padded}"\n---\n\n# Review\n`,
    ).join("; "),
    /description/u,
  );

  // A description within the limit is still accepted, whitespace and all.
  assert.deepEqual(
    problems(
      '---\nname: contract-review\ndescription: "Review a draft.   Use when signing."\n---\n\n# Review\n',
    ),
    [],
  );
});

/**
 * A newly published description has to say when to use the skill.
 *
 * `name` and `description` are the only text a host holds for every installed
 * skill, so the description carries the whole activation decision. `Method for
 * market sizing.` names a subject and gives an agent nothing to match on — the
 * skill is installed and never fires.
 *
 * The rule lives at the publication boundary rather than in the structural
 * checks the repository scan runs, because the catalog already holds skills
 * written before it existed. Those stay grandfathered; what this repository
 * publishes from today does not.
 */
test("a newly published skill whose description says only what it is about is refused", async () => {
  await withTempRepo(async (repoRoot) => {
    await assert.rejects(
      commitAgent({
        repoRoot,
        approvedName: AGENT_NAME,
        personaMarkdown: PERSONA,
        skillPaths: [],
        generatedSkills: [{
          name: "market-sizing",
          body: skillBody("market-sizing", "Method for market sizing."),
        }],
      }),
      /market-sizing/,
    );

    assertNothingPublished(repoRoot);
  });
});

test("a newly published skill that says what and when is published", async () => {
  await withTempRepo(async (repoRoot) => {
    const result = await commitAgent({
      repoRoot,
      approvedName: AGENT_NAME,
      personaMarkdown: PERSONA,
      skillPaths: [],
      generatedSkills: [{
        name: "market-sizing",
        body: skillBody(
          "market-sizing",
          "Size a market from the bottom up. Use when a business case needs a defensible number.",
        ),
      }],
    });

    assert.deepEqual(result.generatedSkills, ["market-sizing"]);
  });
});

/** The repository scan keeps its structural rule, so existing skills stand. */
test("the repository scan still accepts a description written before the rule", () => {
  assert.deepEqual(
    findSkillSpecViolations({
      source: skillBody("market-sizing", "Method for market sizing."),
      folderName: "market-sizing",
      skillPath: "skills/market-sizing/SKILL.md",
    }),
    [],
  );
});
